{
  "shot": {
    "composition": "中景镜头，使用 35mm 焦距，通过 Sony Venice 摄像机拍摄，景深设置为浅景深，以突出主体与背景的层次感，构图采用三分法，主体位于画面右侧三分之一处，城墙与旗帜形成对称性背景。",
    "camera_motion": "静态镜头，无运镜，仅轻微微调对焦以捕捉风动细节，营造静谧凝视的氛围。"
  },
  "subject": {
    "description": "一位 23 岁的东亚女性，面容清秀，眼神低垂，神情哀婉，留着及腰的乌黑长发，发丝柔顺无饰物，身形苗条而纤细，姿态静止如雕塑，仿佛凝固在思念之中。",
    "wardrobe": "身着一件淡黄色渐变至米色的丝质长披风，内衬为淡蓝色汉服裙摆，披风边缘有细腻的金线刺绣，衣料轻盈飘逸，随风自然垂落，下摆与地面接触处形成柔和褶皱。"
  },
  "scene": {
    "location": "一座古代中式城楼的城墙上，砖石结构清晰可见，垛口与瞭望孔排列整齐，背景为开阔的战场或荒野。",
    "time_of_day": "黄昏时分，夕阳即将沉落，天际线泛起柔和的橙红色光晕。",
    "environment": "城墙上空飘着微弱的雾气，风力适中，吹动三面旗帜与披风，地面铺有青灰色石砖，远处无其他人物，环境空旷肃穆，营造出孤独与缅怀的氛围。"
  },
  "visual_details": {
    "action": "风轻拂，旗帜与披风随风轻扬，主体保持静止，仿佛时间凝固，唯有风与光影在动。",
    "props": "三面红色旗帜，旗帜边缘呈锯齿状，中央印有黑色蜘蛛图案，旗杆为黑色金属，城墙由灰白色砖石砌成，垛口呈方形，瞭望孔为小方窗。",
    "action_sequence": [
      "镜头开始时，风从左至右轻拂，左侧旗帜先动，随后中间旗帜随风扬起，披风边缘轻微翻卷。",
      "风力渐强，中间旗帜完全展开，蜘蛛图案清晰可见，披风随之轻摆，形成动态对比。",
      "风势稳定，三面旗帜与披风在风中形成优雅的波浪状摆动，主体仍保持静止，目光凝望远方。",
      "镜头微调，捕捉披风与旗帜的动态细节，风的流动感与静止的主体形成强烈对比。",
      "风势渐弱，旗帜与披风缓缓回落，主体仍伫立原地，仿佛与风共存，思念无声。"
    ]
  },
  "cinematography": {
    "lighting": "柔和的黄昏自然光，从画面左上方斜射，照亮主体披风的边缘与旗帜，形成明暗对比，雾气柔化光线，使整体画面呈现暖色调与冷色调交织的视觉层次。",
    "tone": "沉静、哀婉、史诗感，带有东方古典美学的诗意与孤独感，情感深邃，引人共鸣。"
  }
}
